import RNA
import random
from multiprocessing import Pool

target = "((....))..(...(...(..(.(..(...(((.(((...((((....)))).((((((.((((((.((((((.((((((.((((((((((.((((((.(((((.((((.((((..((((...)))).))).)))))).))))).)))))).)))))))).)))))).)))))).)))))).))))))).)))...(((.(((((.(..((((.(..((((.(..((((.(..(((((((.((((((.(((((.((((((.(((.((((((....))))))..)))).)))).))))).)))))).)))))))).)..)))).)..)))).)..)))).)..))))).((((....))))...))).)))...)..).)..)...)...)..((....))"
n = len(target)
stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

# hairpin caps
hairpins=[]
seen=set()
for i,j in list(pairs.items()):
    if i<j and all(k not in pairs for k in range(i+1,j)):
        hairpins.append((i,j))

def comp_init(rng):
    seq=['A']*n
    for i,j in pairs.items():
        if i<j:
            # randomize which side G/C
            if rng.random()<0.5:
                seq[i]='G'; seq[j]='C'
            else:
                seq[i]='C'; seq[j]='G'
    # caps
    for i,j in hairpins:
        ll=j-i-1
        if ll==4:
            cap=rng.choice(["GAAA","UUCG","GCAA","CUUG"])
        elif ll==3:
            cap=rng.choice(["UUU","GAA","GUA","CUU"])
        else:
            cap="A"*ll
        for k,ch in enumerate(cap):
            seq[i+1+k]=ch
    return ''.join(seq)

def worker(seed):
    rng=random.Random(seed)
    best_seq=None; best_dist=999
    for t in range(8):
        start=comp_init(rng)
        try:
            seq,dist=RNA.inverse_fold(start,target)
            if dist<best_dist:
                best_dist=dist; best_seq=seq
            if dist==0:
                break
        except Exception:
            pass
    return (best_dist,best_seq)

if __name__=='__main__':
    seeds=list(range(64))
    with Pool(16) as p:
        results=p.map(worker,seeds)
    results.sort()
