import RNA
import random
import sys

unit_target = sys.argv[1]
seed = int(sys.argv[2])
iters = int(sys.argv[3])

target = unit_target
n = len(target)
stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

# hairpin caps
hairpins=[]
for i,j in list(pairs.items()):
    if i<j and all(k not in pairs for k in range(i+1,j)):
        hairpins.append((i,j))

def init(rng):
    seq=['A']*n
    for i,j in pairs.items():
        if i<j:
            if rng.random()<0.5: seq[i]='G'; seq[j]='C'
            else: seq[i]='C'; seq[j]='G'
    for i,j in hairpins:
        ll=j-i-1
        if ll==4: cap=rng.choice(["GAAA","UUCG","GCAA","CUUG"])
        elif ll==3: cap=rng.choice(["UUU","GAA","GUA","CUU"])
        else: cap="A"*ll
        for k,ch in enumerate(cap): seq[i+1+k]=ch
    return ''.join(seq)

def score(seq):
    ss,mfe=RNA.fold(seq)
    return RNA.bp_distance(ss,target), ss

rng=random.Random(seed)
best_seq=None; best_d=9999
cur=init(rng)
cur_d,cur_ss=score(cur)
best_d=cur_d; best_seq=cur
T=2.0
for it in range(iters):
    T=max(0.05, 2.0*(1-it/iters))
    # mutate 1-2 positions
    new=list(cur)
    k=rng.randint(1,2)
    for _ in range(k):
        pos=rng.randrange(n)
        new[pos]=rng.choice("ACGU")
    new_s=''.join(new)
    new_d,new_ss=score(new_s)
    if new_d<cur_d or rng.random()<pow(2.718,-(new_d-cur_d)/max(T,0.01)):
        cur=new_s; cur_d=new_d; cur_ss=new_ss
        if cur_d<best_d:
            best_d=cur_d; best_seq=cur_s=cur
            if best_d==0: break
print("BEST_DIST", best_d)
print(best_seq)
